  <div class="slide-list"><?php foreach($slides as $slideIndex=>$s):?><article class="slide-row slider-row"><?php if($s['media_type']==='video'):?><video controls preload="metadata" src="<?=e($s['video_url'])?>"></video><?php else:?><img src="<?=e($s['image_url'])?>" alt="<?=e($s['alt_text'])?>"><?php endif;?><div class="slide-meta"><strong><?=e($s['title']?:($s['alt_text']?:'Başlıksız slider'))?></strong><small><?=e($s['media_type']==='video'?'Video':'Görsel')?> · <?=trim((string)$s['subtitle'])!==''?'Alt yazılı':'Yazısız'?> · <?=$s['is_published']?'Yayında':'Taslak'?></small></div><div class="slider-row-actions"><form method="post" action="/panel/index.php"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="device" value="<?=e($device)?>"><input type="hidden" name="direction" value="up"><button class="icon-button" name="move" value="<?=e((string)$s['id'])?>" aria-label="Yukarı taşı" <?=$slideIndex===0?'disabled':''?> type="submit">↑</button></form><form method="post" action="/panel/index.php"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="device" value="<?=e($device)?>"><input type="hidden" name="direction" value="down"><button class="icon-button" name="move" value="<?=e((string)$s['id'])?>" aria-label="Aşağı taşı" <?=$slideIndex===count($slides)-1?'disabled':''?> type="submit">↓</button></form><button type="button" class="secondary" onclick='editSlide(<?=json_encode($s,JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP)?>)'>Düzenle</button><form method="post" action="/panel/index.php" onsubmit="return confirm('Slider silinsin mi?')"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="device" value="<?=e($device)?>"><button class="danger" name="delete" value="<?=e((string)$s['id'])?>">Sil</button></form></div></article><?php endforeach;?><?php if(!$slides):?><div class="empty-state">Bu cihaz için henüz slider eklenmemiş.</div><?php endif;?></div>
