<script>
const sliderForm=document.querySelector('#editor'),sliderType=sliderForm.elements.media_type,sliderFile=sliderForm.elements.media,sliderCard=document.querySelector('#slider-editor'),sliderDevice='<?=e($device)?>';
function setSliderAccept(){sliderFile.accept=sliderType.value==='video'?'video/mp4,video/webm':'image/jpeg,image/png,image/webp';sliderFile.required=!sliderForm.elements.id.value;document.querySelector('#media-size-note').textContent=sliderDevice==='desktop'?'Önerilen ölçü: 3840 × 2160 px.':'Önerilen ölçü: 1080 × 1920 px.'}
sliderType.addEventListener('change',setSliderAccept);
function editSlide(s){sliderForm.reset();sliderForm.elements.id.value=s.id;sliderForm.elements.device.value=s.device||sliderDevice;sliderType.value=s.media_type;sliderForm.elements.sort_order.value=s.sort_order;sliderForm.elements.alt_text.value=s.alt_text||'';sliderForm.elements.title.value=s.title||'';sliderForm.elements.title_color.value=s.title_color||'#ffffff';sliderForm.elements.subtitle.value=s.subtitle||'';sliderForm.elements.subtitle_color.value=s.subtitle_color||'#ffffff';sliderForm.elements.link_url.value=s.link_url||'';sliderForm.elements.hotspot_enabled.checked=!!Number(s.hotspot_enabled);sliderForm.elements.hotspot_x.value=s.hotspot_x??10;sliderForm.elements.hotspot_y.value=s.hotspot_y??70;sliderForm.elements.hotspot_width.value=s.hotspot_width??28;sliderForm.elements.hotspot_height.value=s.hotspot_height??18;sliderForm.elements.is_published.checked=!!Number(s.is_published);sliderFile.value='';setSliderAccept();sliderCard.hidden=false;document.querySelector('#slider-editor-title').textContent='Sliderı düzenle';sliderCard.scrollIntoView({behavior:'smooth',block:'start'})}
document.querySelector('#slider-add').addEventListener('click',()=>{sliderForm.reset();sliderForm.elements.id.value='';sliderForm.elements.device.value=sliderDevice;sliderForm.elements.sort_order.value='<?=count($slides)?>';sliderForm.elements.title_color.value='#ffffff';sliderForm.elements.subtitle_color.value='#ffffff';sliderForm.elements.is_published.checked=true;sliderFile.value='';setSliderAccept();sliderCard.hidden=false;document.querySelector('#slider-editor-title').textContent='Slider ekle';sliderCard.scrollIntoView({behavior:'smooth',block:'start'})});
document.querySelector('#slider-cancel').addEventListener('click',()=>sliderCard.hidden=true);
</script>
